run: order_items -> {
  aggregate:
    lines is count()
    avg_line_discount is avg(1 - sale_price / products.retail_price)
    weighted_discount is 1 - sum(sale_price) / sum(products.retail_price)
    avg_sale is avg(sale_price)
    avg_list is avg(products.retail_price)
    lines_above_list is count() { where: sale_price > products.retail_price }
    lines_below_list is count() { where: sale_price < products.retail_price }
